import io, json, os, time, urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
MODEL = 'qwen2.5:14b'
TIMEOUT = 1500
LANE = 'cpu'
CPU_THREADS = 4      # CEO 10% CPU margin law (O-20260913-2215)
GENERATE_URL = 'http://localhost:11434/api/generate'
MATERIAL = 'MC-20261014-DIGEST-v20 static card (cards.json + render output + e4-material.md)'
prompt = '你是一名刷公众号图文/信息流的普通读者，看到下面这张静态盘点卡《城市盘点 020》\n（1080×1080 方图·黑底；左上角小字「[AIGC·AI 生成内容]」；顶部大标题「城市盘点 020」）。\n图上写着：\n「死线冲刺日（10-13·43 行台账 18 道 CEO 令）」——这行是城市台账数字盘点：10-13 单日 43 行令批台账，其中 18 道是老板亲颁的令；\n「应该说 每个块面都要是全球一流的，」；\n「不要出来垃圾玩艺」——这两行是老板当天的原话；\n「每块全球一流律 · 闸 > 死线 · 产线母法」——公司把这句原话立成产线母法：质量闸比死线大，产出不达基准禁出厂；\n「复评 60 分 · 整改九项 · 90 分入片库门槛」——旗舰音乐片当天被老板复评 60 分，连颁九项整改令，入片库门槛提到 90 分；\n「全席调研 9/9 归笼 · 四专 41 曲全量重制立项」——九组专家调研当天全部归笼，四张早期专辑 41 首经典歌曲全量 AI 重制立项；\n「全本地验证 · CPU 常开 · 云端放开」——同日三道资源令收尾。\n图内底部声明行「基于硅基城市真实事件（死线冲刺日令批台账档案）」。\n背景：硅基城市是一家由 AI 全自主运转的公司集团（只有一个人类老板，其余成员全是 AI）。\n「城市盘点」系列是集团旗下媒体公司出品的数字盘点卡——把城市自己台账里的真实事件与数字原样盘点出来，不虚构不加工。\n本卡的背景是：10-13 是死线冲刺日——凌晨赶片到死线、迟到后手工收口、老板复评只给 60 分；\n然后一整天连颁 18 道令：整改、调研、立项；而当天最高的一道令是「每块全球一流律」——\n赶死线的日子，最高令反而是质量闸比死线大。\n请回答三个问题，每题一段，直说不委婉：\n1) 刷到这张卡你会停下来看吗？会保存或转发给朋友吗？打几分（0-10）？为什么？\n2) 有没有一眼假、空洞套话的地方？有的话扣几分、指出原句？\n3) 最弱的一项是什么？'

result = {'ts': time.strftime('%Y-%m-%d %H:%M:%S'), 'model': MODEL,
          'material': MATERIAL, 'lane': LANE}
payload = json.dumps({'model': MODEL, 'prompt': prompt, 'stream': False,
                      'options': {'num_gpu': 0,
                                  'num_thread': CPU_THREADS}}).encode('utf-8')
request = urllib.request.Request(GENERATE_URL, data=payload,
                                 headers={'Content-Type': 'application/json'})
try:
    with urllib.request.urlopen(request, timeout=TIMEOUT) as resp:
        body = json.loads(resp.read().decode('utf-8', 'replace'))
    result['verdict'] = (body.get('response') or '').strip() or \
        'EMPTY-RESPONSE'
except Exception as exc:
    text = '%s: %s' % (type(exc).__name__, exc)
    if 'timed out' in text.lower() or 'timeout' in text.lower():
        result['verdict'] = 'TIMEOUT-%ds' % TIMEOUT
    else:
        print('TRANSPORT-ERROR %s' % text, flush=True)
        raise SystemExit(3)
io.open(os.path.join(HERE, 'e4-result.json'), 'w', encoding='utf-8').write(
    json.dumps(result, ensure_ascii=False, indent=2))
print('DONE' if not result['verdict'].startswith('TIMEOUT') else 'TIMEOUT')
